return function(c) local s=c.state if s<0 or s>1000000 then s=0 end local n=s+1 if n>1000000 then n=0 end local beat=s%4 if beat==0 then return {dx=0,dy=0,state=n} end local h=c.history local len=#h if len<1 then return {dx=0,dy=0,state=n} end if len>8 then len=8 end local idx=len if beat==1 then idx=len-3 if idx<1 then idx=1 end elseif beat==3 then idx=len-1 if idx<1 then idx=1 end end local p=h[idx] local tx=p.x local ty=p.y local dx=0 local dy=0 if tx>c.mx then dx=1 elseif tx<c.mx then dx=-1 end if ty>c.my then dy=1 elseif ty<c.my then dy=-1 end return {dx=dx,dy=dy,state=n} end